import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Select top features based on t-statistic
    selected_features = []
    for fid in feats.ids:
        col_idx = feats.column(fid)
        t_stat = abs(feats.x[:, col_idx].T @ (feats.y * 2 - 1) / (np.std(feats.x[:, col_idx]) * len(feats.y)**0.5))
        if t_stat > 1.5:
            selected_features.append(fid)

    # Sort by effect size (t-statistic)
    def get_t_stat(fid):
        col_idx = feats.column(fid)
        return abs(feats.x[:, col_idx].T @ (feats.y * 2 - 1) / (np.std(feats.x[:, col_idx]) * len(feats.y)**0.5))

    selected_features.sort(key=get_t_stat, reverse=True)

    # Take top candidates, limited to MAX_DRIVERS
    drivers = tuple(selected_features[:MAX_DRIVERS])

    # For logistic regression, include all selected features
    columns = tuple(selected_features)

    # Product terms: pair top features
    products = []
    for i in range(min(3, len(selected_features))):
        for j in range(i+1, min(3, len(selected_features))):
            products.append((selected_features[i], selected_features[j]))

    # Weighted score: use top feature's standardized value
    loadings = {fid: 1.0 for fid in selected_features[:1]}

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
